import numpy as np
from scipy.optimize import least_squares
one=np.ones_like(t)
def build(w,cols_extra):
    return np.column_stack([one,x,v,x**2,x*v,v**2,x**3,np.cos(w*t),np.sin(w*t)]+cols_extra)
def run(extra,label):
    def resid(p):
        A=build(p[0],extra); c,_,_,_=np.linalg.lstsq(A,dv_dt,rcond=None); return A@c-dv_dt
    best=None
    for w0 in np.linspace(0.1,1.5,15):
        r=least_squares(resid,[w0])
        e=np.mean(r.fun**2)/np.var(dv_dt)
        if best is None or e<best[0]: best=(e,r.x)
    print(label,best)
